import React, { useState, useEffect } from "react";
import "./Filter.css";

const createInitialState = (filters) => {
  const state = {};
  Object.keys(filters).forEach((key) => {
    state[key] = new Set();
  });
  return state;
};

const Filter = ({ filters, onChange }) => {
  const [selected, setSelected] = useState(() =>
    createInitialState(filters)
  );

  useEffect(() => {
    onChange(selected);
  }, [selected, onChange]);

  const toggleValue = (category, value) => {
    const updated = new Set(selected[category]);

    if (updated.has(value)) updated.delete(value);
    else updated.add(value);

    setSelected({
      ...selected,
      [category]: updated,
    });
  };

  const resetFilters = () => {
    const cleared = createInitialState(filters);
    setSelected(cleared);
    onChange(cleared);
  };

  const renderCheckbox = (category, value, isRating = false) => (
    <label key={value} className="filter-option">
      <input
        type="checkbox"
        checked={selected[category].has(value)}
        onChange={() => toggleValue(category, value)}
      />
      {isRating ? (
        <span className="filter-stars">
          {"★".repeat(value)}
        </span>
      ) : (
        <span className="filter-text">{value}</span>
      )}
    </label>
  );

  const renderTag = (category, value) => (
    <button
      key={value}
      className={`tag-btn ${
        selected[category].has(value) ? "active" : ""
      }`}
      onClick={() => toggleValue(category, value)}
      type="button"
    >
      {value}
    </button>
  );

  return (
    <aside className="filter-sidebar">
      <div className="filter-header">
        <span className="filter-header-title">Фильтр</span>
        <button
          className="filter-reset"
          onClick={resetFilters}
          type="button"
        >
          Сбросить
        </button>
      </div>

      {Object.entries(filters).map(([category, values]) => (
        <div key={category} className="filter-block">
          <div className="filter-title">{category}</div>

          <div
            className={`filter-box ${
              category === "Тэги" ? "row" : "column"
            }`}
          >
            {category === "Тэги"
              ? values.map((v) => renderTag(category, v))
              : values.map((v) =>
                  renderCheckbox(
                    category,
                    v,
                    category === "Рейтинг"
                  )
                )}
          </div>
        </div>
      ))}
    </aside>
  );
};

export default Filter;
